window.CHUJI_DATA_8 = [{"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 1, "type": "reading", "en": "My best friend Billy and I decided to learn English last year.", "zh": "我和挚友比利去年决心要学英文。", "audio": "chuji_l71_01.mp3", "localAudio": "audio_chunks/chuji_l71_01.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 2, "type": "reading", "en": "We promised each other to work hard.", "zh": "我们彼此允诺要努力学习。", "audio": "chuji_l71_02.mp3", "localAudio": "audio_chunks/chuji_l71_02.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 3, "type": "reading", "en": "We never failed to attend class.", "zh": "我们从不缺课。", "audio": "chuji_l71_03.mp3", "localAudio": "audio_chunks/chuji_l71_03.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 4, "type": "reading", "en": "Billy always remembered to do his homework.", "zh": "比利总是会记得做功课。", "audio": "chuji_l71_04.mp3", "localAudio": "audio_chunks/chuji_l71_04.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 5, "type": "reading", "en": "I never forgot to do mine, either.", "zh": "而我也从未忘记做自己的功课。", "audio": "chuji_l71_05.mp3", "localAudio": "audio_chunks/chuji_l71_05.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 6, "type": "reading", "en": "Our English is pretty good now.", "zh": "我们的英文现在很不错了。", "audio": "chuji_l71_06.mp3", "localAudio": "audio_chunks/chuji_l71_06.mp3", "b64": "", "src": "chuji"}, {"l": 371, "lt": "Lesson 71 Working Hard 努力学习", "i": 7, "type": "reading", "en": "It only proves that there's no gain without pain.", "zh": "这就证明了一分耕耘，一分收获的道理。", "audio": "chuji_l71_07.mp3", "localAudio": "audio_chunks/chuji_l71_07.mp3", "b64": "", "src": "chuji"}, {"l": 372, "lt": "Lesson 72 Remember to Wash 别忘了漱洗", "i": 1, "type": "dialog", "en": "Don't forget to brush your teeth before you go to bed!", "zh": "睡觉前别忘了要刷牙！", "audio": "chuji_l72_01.mp3", "localAudio": "audio_chunks/chuji_l72_01.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 372, "lt": "Lesson 72 Remember to Wash 别忘了漱洗", "i": 2, "type": "dialog", "en": "Yes, Mom.", "zh": "是的，母亲。", "audio": "chuji_l72_02.mp3", "localAudio": "audio_chunks/chuji_l72_02.mp3", "b64": "", "src": "chuji", "speaker": "Micky", "note": "说话人: Micky"}, {"l": 372, "lt": "Lesson 72 Remember to Wash 别忘了漱洗", "i": 3, "type": "dialog", "en": "And remember to wash your hands before meals.", "zh": "而且吃饭前要记得洗手。", "audio": "chuji_l72_03.mp3", "localAudio": "audio_chunks/chuji_l72_03.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 372, "lt": "Lesson 72 Remember to Wash 别忘了漱洗", "i": 4, "type": "dialog", "en": "Yes, Mom. Anything else?", "zh": "是的，母亲。还有其他的事吗？", "audio": "chuji_l72_04.mp3", "localAudio": "audio_chunks/chuji_l72_04.mp3", "b64": "", "src": "chuji", "speaker": "Micky", "note": "说话人: Micky"}, {"l": 372, "lt": "Lesson 72 Remember to Wash 别忘了漱洗", "i": 5, "type": "dialog", "en": "Yes, remind me to tell your sister the same thing.", "zh": "有的，要提醒我告诉你妹妹同样的事。", "audio": "chuji_l72_05.mp3", "localAudio": "audio_chunks/chuji_l72_05.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 1, "type": "reading", "en": "Joe is learning how to cook.", "zh": "乔正在学习如何烹饪。", "audio": "chuji_l73_01.mp3", "localAudio": "audio_chunks/chuji_l73_01.mp3", "b64": "", "src": "chuji"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 2, "type": "reading", "en": "He has to learn because he wants to start a small restaurant.", "zh": "他必须要学，因为他想要开一家小餐厅。", "audio": "chuji_l73_02.mp3", "localAudio": "audio_chunks/chuji_l73_02.mp3", "b64": "", "src": "chuji"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 3, "type": "reading", "en": "His mother is teaching him.", "zh": "他母亲正在教他。", "audio": "chuji_l73_03.mp3", "localAudio": "audio_chunks/chuji_l73_03.mp3", "b64": "", "src": "chuji"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 4, "type": "reading", "en": "She used to be a chef at a big restaurant.", "zh": "她曾在一家大餐厅当过厨师。", "audio": "chuji_l73_04.mp3", "localAudio": "audio_chunks/chuji_l73_04.mp3", "b64": "", "src": "chuji"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 5, "type": "reading", "en": "With her help, he ought to have no problem.", "zh": "有了她的帮助，他应当不会有什么问题。", "audio": "chuji_l73_05.mp3", "localAudio": "audio_chunks/chuji_l73_05.mp3", "b64": "", "src": "chuji"}, {"l": 373, "lt": "Lesson 73 Joe's Restaurant 乔的餐厅", "i": 6, "type": "reading", "en": "I'm sure Joe's restaurant is going to be the best restaurant in town.", "zh": "我确信乔的餐厅将成为镇上最好的餐厅。", "audio": "chuji_l73_06.mp3", "localAudio": "audio_chunks/chuji_l73_06.mp3", "b64": "", "src": "chuji"}, {"l": 374, "lt": "Lesson 74 You Ought to Learn to Swim 你应当学习游泳", "i": 1, "type": "dialog", "en": "Do you know how to swim?", "zh": "你知道怎么游泳吗？", "audio": "chuji_l74_01.mp3", "localAudio": "audio_chunks/chuji_l74_01.mp3", "b64": "", "src": "chuji", "speaker": "Adam", "note": "说话人: Adam"}, {"l": 374, "lt": "Lesson 74 You Ought to Learn to Swim 你应当学习游泳", "i": 2, "type": "dialog", "en": "No, I don't.", "zh": "不，我不知道。", "audio": "chuji_l74_02.mp3", "localAudio": "audio_chunks/chuji_l74_02.mp3", "b64": "", "src": "chuji", "speaker": "Eva", "note": "说话人: Eva"}, {"l": 374, "lt": "Lesson 74 You Ought to Learn to Swim 你应当学习游泳", "i": 3, "type": "dialog", "en": "You ought to learn.", "zh": "你应当学习。", "audio": "chuji_l74_03.mp3", "localAudio": "audio_chunks/chuji_l74_03.mp3", "b64": "", "src": "chuji", "speaker": "Adam", "note": "说话人: Adam"}, {"l": 374, "lt": "Lesson 74 You Ought to Learn to Swim 你应当学习游泳", "i": 4, "type": "dialog", "en": "Why?", "zh": "为什么？", "audio": "chuji_l74_04.mp3", "localAudio": "audio_chunks/chuji_l74_04.mp3", "b64": "", "src": "chuji", "speaker": "Eva", "note": "说话人: Eva"}, {"l": 374, "lt": "Lesson 74 You Ought to Learn to Swim 你应当学习游泳", "i": 5, "type": "dialog", "en": "Well, maybe you'll have to save me one day.", "zh": "嗯，也许有一天你将必须救我。", "audio": "chuji_l74_05.mp3", "localAudio": "audio_chunks/chuji_l74_05.mp3", "b64": "", "src": "chuji", "speaker": "Adam", "note": "说话人: Adam"}, {"l": 375, "lt": "Lesson 75 Michael's Dream 迈克的梦想", "i": 1, "type": "reading", "en": "Michael wanted to be a musician, but his mother wanted him to be a doctor.", "zh": "迈克想要当音乐家，但他的母亲却希望他成为一名医生。", "audio": "chuji_l75_01.mp3", "localAudio": "audio_chunks/chuji_l75_01.mp3", "b64": "", "src": "chuji"}, {"l": 375, "lt": "Lesson 75 Michael's Dream 迈克的梦想", "i": 2, "type": "reading", "en": "Michael didn't want to make his mother feel sad, so he decided to obey her.", "zh": "迈克不想使他的母亲感到难过，因此他决定听她的话。", "audio": "chuji_l75_02.mp3", "localAudio": "audio_chunks/chuji_l75_02.mp3", "b64": "", "src": "chuji"}, {"l": 375, "lt": "Lesson 75 Michael's Dream 迈克的梦想", "i": 3, "type": "reading", "en": "Rather than play music, he studied medicine.", "zh": "他没有演奏音乐而改学医去了。", "audio": "chuji_l75_03.mp3", "localAudio": "audio_chunks/chuji_l75_03.mp3", "b64": "", "src": "chuji"}, {"l": 375, "lt": "Lesson 75 Michael's Dream 迈克的梦想", "i": 4, "type": "reading", "en": "Unfortunately, Michael failed to graduate from medical school.", "zh": "不幸的是，迈克未能从医学院毕业。", "audio": "chuji_l75_04.mp3", "localAudio": "audio_chunks/chuji_l75_04.mp3", "b64": "", "src": "chuji"}, {"l": 375, "lt": "Lesson 75 Michael's Dream 迈克的梦想", "i": 5, "type": "reading", "en": "However, he isn't sad because he is now a famous musician.", "zh": "然而，他并不难过，因为他现在成了一位知名的音乐家。", "audio": "chuji_l75_05.mp3", "localAudio": "audio_chunks/chuji_l75_05.mp3", "b64": "", "src": "chuji"}, {"l": 376, "lt": "Lesson 76 I Want to Be a Doctor 我想当医生", "i": 1, "type": "dialog", "en": "What do you want to be when you grow up?", "zh": "你长大以后想要当什么？", "audio": "chuji_l76_01.mp3", "localAudio": "audio_chunks/chuji_l76_01.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 376, "lt": "Lesson 76 I Want to Be a Doctor 我想当医生", "i": 2, "type": "dialog", "en": "I want to be a doctor.", "zh": "我想当医生。", "audio": "chuji_l76_02.mp3", "localAudio": "audio_chunks/chuji_l76_02.mp3", "b64": "", "src": "chuji", "speaker": "Child", "note": "说话人: Child"}, {"l": 376, "lt": "Lesson 76 I Want to Be a Doctor 我想当医生", "i": 3, "type": "dialog", "en": "Why?", "zh": "为什么？", "audio": "chuji_l76_03.mp3", "localAudio": "audio_chunks/chuji_l76_03.mp3", "b64": "", "src": "chuji", "speaker": "Mother", "note": "说话人: Mother"}, {"l": 376, "lt": "Lesson 76 I Want to Be a Doctor 我想当医生", "i": 4, "type": "dialog", "en": "I want to help sick people.", "zh": "我想要帮助生病的人。", "audio": "chuji_l76_04.mp3", "localAudio": "audio_chunks/chuji_l76_04.mp3", "b64": "", "src": "chuji", "speaker": "Child", "note": "说话人: Child"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 1, "type": "reading", "en": "Learning English is like building a house.", "zh": "学英文就像盖房子一样。", "audio": "chuji_l77_01.mp3", "localAudio": "audio_chunks/chuji_l77_01.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 2, "type": "reading", "en": "Laying a strong foundation is the first and most important step.", "zh": "奠定扎实的基础是第一步也是最重要的一步。", "audio": "chuji_l77_02.mp3", "localAudio": "audio_chunks/chuji_l77_02.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 3, "type": "reading", "en": "In other words, you should read and speak English every day.", "zh": "换句话说，你应该每天读英文和说英文。", "audio": "chuji_l77_03.mp3", "localAudio": "audio_chunks/chuji_l77_03.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 4, "type": "reading", "en": "Memorizing new words and phrases is also helpful.", "zh": "记新的单词和短语也是很有帮助的。", "audio": "chuji_l77_04.mp3", "localAudio": "audio_chunks/chuji_l77_04.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 5, "type": "reading", "en": "Like building a house, learning English takes some time.", "zh": "就像盖房子一样，学英文需要一些时间。", "audio": "chuji_l77_05.mp3", "localAudio": "audio_chunks/chuji_l77_05.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 6, "type": "reading", "en": "So don't be impatient.", "zh": "因此不要没有耐心。", "audio": "chuji_l77_06.mp3", "localAudio": "audio_chunks/chuji_l77_06.mp3", "b64": "", "src": "chuji"}, {"l": 377, "lt": "Lesson 77 Rome Wasn't Built in a Day 罗马不是一天造成的", "i": 7, "type": "reading", "en": "Remember, \"Rome wasn't built in a day.\"", "zh": "记住：“罗马不是一天造成的。”", "audio": "chuji_l77_07.mp3", "localAudio": "audio_chunks/chuji_l77_07.mp3", "b64": "", "src": "chuji"}, {"l": 378, "lt": "Lesson 78 Don't Be Discouraged 不要泄气", "i": 1, "type": "dialog", "en": "Your written English is fairly good, but your spoken English needs improvement.", "zh": "你的英文文笔还不错，但你的英文口语就需要加强了。", "audio": "chuji_l78_01.mp3", "localAudio": "audio_chunks/chuji_l78_01.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 378, "lt": "Lesson 78 Don't Be Discouraged 不要泄气", "i": 2, "type": "dialog", "en": "I know, but speaking English is difficult.", "zh": "我知道，但讲英文很难啊。", "audio": "chuji_l78_02.mp3", "localAudio": "audio_chunks/chuji_l78_02.mp3", "b64": "", "src": "chuji", "speaker": "Student", "note": "说话人: Student"}, {"l": 378, "lt": "Lesson 78 Don't Be Discouraged 不要泄气", "i": 3, "type": "dialog", "en": "Don't be discouraged. Practice makes perfect.", "zh": "不要泄气。熟能生巧嘛。", "audio": "chuji_l78_03.mp3", "localAudio": "audio_chunks/chuji_l78_03.mp3", "b64": "", "src": "chuji", "speaker": "Teacher", "note": "说话人: Teacher"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 1, "type": "reading", "en": "Many people are fond of showing off.", "zh": "有很多人喜欢炫耀。", "audio": "chuji_l79_01.mp3", "localAudio": "audio_chunks/chuji_l79_01.mp3", "b64": "", "src": "chuji"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 2, "type": "reading", "en": "They always insist on footing the bill when they are out with friends.", "zh": "当他们和朋友外出时总是争着付帐。", "audio": "chuji_l79_02.mp3", "localAudio": "audio_chunks/chuji_l79_02.mp3", "b64": "", "src": "chuji"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 3, "type": "reading", "en": "They always think of impressing people with their wealth.", "zh": "他们老是想用自己的财富给别人留下深刻的印象。", "audio": "chuji_l79_03.mp3", "localAudio": "audio_chunks/chuji_l79_03.mp3", "b64": "", "src": "chuji"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 4, "type": "reading", "en": "They seem to think that money can buy friends.", "zh": "他们似乎认为钱可以买到朋友。", "audio": "chuji_l79_04.mp3", "localAudio": "audio_chunks/chuji_l79_04.mp3", "b64": "", "src": "chuji"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 5, "type": "reading", "en": "In fact, it can't.", "zh": "但事实上，钱无法买到朋友。", "audio": "chuji_l79_05.mp3", "localAudio": "audio_chunks/chuji_l79_05.mp3", "b64": "", "src": "chuji"}, {"l": 379, "lt": "Lesson 79 Showing Off 炫耀", "i": 6, "type": "reading", "en": "Instead of trying to show off, they should be themselves.", "zh": "他们不应炫耀，而应做真正的自我。", "audio": "chuji_l79_06.mp3", "localAudio": "audio_chunks/chuji_l79_06.mp3", "b64": "", "src": "chuji"}, {"l": 380, "lt": "Lesson 80 I'm Good at Cooking 我擅长烹饪", "i": 1, "type": "dialog", "en": "Are you good at sewing?", "zh": "你对缝纫很在行吗？", "audio": "chuji_l80_01.mp3", "localAudio": "audio_chunks/chuji_l80_01.mp3", "b64": "", "src": "chuji", "speaker": "Marty", "note": "说话人: Marty"}, {"l": 380, "lt": "Lesson 80 I'm Good at Cooking 我擅长烹饪", "i": 2, "type": "dialog", "en": "No, but I'm good at cooking. What about you?", "zh": "不，但我对烹饪很在行。你呢？", "audio": "chuji_l80_02.mp3", "localAudio": "audio_chunks/chuji_l80_02.mp3", "b64": "", "src": "chuji", "speaker": "Becky", "note": "说话人: Becky"}, {"l": 380, "lt": "Lesson 80 I'm Good at Cooking 我擅长烹饪", "i": 3, "type": "dialog", "en": "I'm not good at cooking, but I'm fond of eating.", "zh": "我对烹饪不在行，但我却很喜欢吃。", "audio": "chuji_l80_03.mp3", "localAudio": "audio_chunks/chuji_l80_03.mp3", "b64": "", "src": "chuji", "speaker": "Marty", "note": "说话人: Marty"}];